def main():
    canonical=json.loads((ROOT/'docs/ssw-workspace/hospitality/source-v2-planning-translation-source.json').read_text())['lessons']
    for locale,patch in TEXT.items():
        p=D/'translations'/locale/'planning.json';data=json.loads(p.read_text())
        for index,source in enumerate(canonical):
            target=next(l for l in data['lessons'] if l['id']==source['id'])
            assert len(target['questions'])==5, (locale,source['id'],'unexpected/already applied baseline')
            assert [s['id'] for s in target['sections']]==[s['id'] for s in source['sections']]
            if index==0:target['sections'][0]['body']=patch['needs']
            else:target['sections'][3]['body']=patch['local']
            authored=patch['q'][:5] if index==0 else patch['q'][5:]
            assert len(source['questions'])-5==len(authored)
            for q,(prompt,choices,explanation) in zip(source['questions'][5:],authored):
                target['questions'].append({**q,'prompt':prompt,'choices':choices,'explanation':explanation})
            target['sourceRevision']=source['revision'];target['status']='translated_ai_unreviewed'
        p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'locales':list(TEXT),'updatedLessonLocalePairs':10,'newQuestionLocalePairs':40,'bodyFieldsUpdated':10}))

if __name__=='__main__':main()
